<script setup>
import { computed, nextTick, ref, watch } from "vue";
import { BookOpen, Check, ClipboardList, Cpu, Info, Search, Settings2, UserRound, X } from "@lucide/vue";
import { filterSettingsNavigation, settingsNavigation } from "../lib/settings-sections";
import LocalAccountSettings from "./LocalAccountSettings.vue";
import AboutSettings from "./AboutSettings.vue";
import SettingsWorkspace from "./SettingsWorkspace.vue";
const props=defineProps({open:Boolean,section:{type:String,default:"account"},accounts:{type:Array,default:()=>[]},info:Object,profile:{type:Object,required:true},saveProfile:{type:Function,required:true},update:{type:Object,required:true},autoCheck:Boolean,checkUpdates:Function,setAutoCheck:Function,openExternal:Function,openData:Function,openLogs:Function});
const emit=defineEmits(["close","update:section","saved","model-saved","platforms","setup"]);
const icons={account:UserRound,model:Cpu,assignments:ClipboardList,learning:BookOpen,system:Settings2,about:Info};
const dialog=ref(null),content=ref(null),query=ref(""),initialized=ref(false),configurationSection=ref("model"),feedback=ref(""),feedbackError=ref(false);
const current=computed(()=>settingsNavigation.find(item=>item.id===props.section)||settingsNavigation[0]);
const filtered=computed(()=>filterSettingsNavigation(query.value));
const groups=computed(()=>[...new Set(filtered.value.map(item=>item.group))]);
const isConfiguration=computed(()=>["model","assignments","learning","system"].includes(current.value.id));
let trigger;
watch(()=>props.open,async open=>{if(open){trigger=document.activeElement;initialized.value=true;query.value="";await nextTick();dialog.value?.focus();}else if(trigger?.isConnected)trigger.focus();},{immediate:true});
watch(()=>props.section,async section=>{if(["model","assignments","learning","system"].includes(section))configurationSection.value=section;feedback.value="";await nextTick();if(content.value)content.value.scrollTop=0;},{immediate:true});
watch(query,()=>{if(filtered.value.length&&!filtered.value.some(item=>item.id===props.section))emit("update:section",filtered.value[0].id);});
function trap(event){const items=[...dialog.value.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),a[href],textarea:not(:disabled)')].filter(item=>item.getClientRects().length);const first=items[0],last=items.at(-1);if(event.shiftKey&&[first,dialog.value].includes(document.activeElement)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
async function directory(kind){feedback.value="";feedbackError.value=false;try{const ok=await(kind==="data"?props.openData:props.openLogs)();if(!ok)throw new Error("目录操作未完成，请检查本地服务与剪贴板权限。");feedback.value=(kind==="logs"||window.desktopApi)?"已打开"+(kind==="data"?"数据":"日志")+"目录":"已复制"+(kind==="data"?"数据":"日志")+"目录";return true;}catch(error){feedbackError.value=true;feedback.value=error.message;return false;}}
</script>
<template><Teleport to="body"><Transition name="settings-dialog"><div v-if="initialized" v-show="open" class="modal-backdrop settings-backdrop" @mousedown.self="emit('close')" @keydown.esc.stop="emit('close')" @keydown.tab.stop="trap"><section id="application-settings-dialog" ref="dialog" class="modal-card application-settings-dialog" role="dialog" aria-modal="true" aria-labelledby="application-settings-title" tabindex="-1"><aside class="application-settings-sidebar"><h1>设置</h1><label class="search-field"><Search :size="14" /><input v-model="query" type="search" placeholder="搜索设置" aria-label="搜索设置"></label><nav aria-label="设置分类"><section v-for="group in groups" :key="group"><h3>{{group}}</h3><button v-for="item in filtered.filter(item=>item.group===group)" :key="item.id" class="settings-section-button" :class="{active:section===item.id}" type="button" :aria-current="section===item.id?'page':undefined" @click="emit('update:section',item.id)"><component :is="icons[item.id]" :size="16" /><span>{{item.label}}</span></button></section><p v-if="!filtered.length" class="settings-no-match">没有匹配设置</p></nav></aside><div class="application-settings-main"><header class="application-settings-header"><h2 id="application-settings-title"><component :is="icons[current.id]" :size="20" />{{current.id==='account'?'本地账户':current.label}}</h2><button class="icon-button settings-close" type="button" aria-label="关闭设置" title="关闭" @click="emit('close')"><X :size="19" /></button></header><div v-if="feedback" class="settings-directory-feedback" :class="{error:feedbackError}" role="status"><Check v-if="!feedbackError" :size="14" />{{feedback}}</div><div ref="content" class="application-settings-content"><div v-if="!filtered.length" class="settings-search-empty"><Search :size="26" /><h3>没有找到设置</h3><button class="button light" type="button" @click="query=''">清除搜索</button></div><div v-show="filtered.length" class="settings-content-sections"><LocalAccountSettings v-show="current.id==='account'" :profile="profile" :save-profile="saveProfile" /><SettingsWorkspace v-show="isConfiguration" embedded :section="configurationSection" :accounts="accounts" :info="info" @update:section="emit('update:section',$event)" @saved="emit('saved',$event)" @model-saved="emit('model-saved')" @open-data="directory('data')" @open-logs="directory('logs')" @platforms="emit('platforms')" /><AboutSettings v-show="current.id==='about'" :update="update" :auto-check="autoCheck" :check-updates="checkUpdates" :set-auto-check="setAutoCheck" :open-external="openExternal" :open-logs="()=>directory('logs')" @setup="emit('setup')" /></div></div></div></section></div></Transition></Teleport></template>
<style scoped>
/* finesse · component: application-settings · register=product · tokens: inherited */
.settings-backdrop{z-index:90;padding:24px;}.application-settings-dialog{display:grid;grid-template-columns:216px minmax(0,1fr);width:min(1120px,calc(100vw - 48px));height:min(780px,calc(100dvh - 48px));max-height:calc(100dvh - 48px);padding:0;overflow:hidden;outline:none;background:var(--surface);}.application-settings-sidebar{display:flex;flex-direction:column;gap:18px;min-height:0;padding:24px 14px 20px;border-right:1px solid var(--line);background:var(--bg);}.application-settings-sidebar>h1{font-size:18px;padding:0 9px;}.application-settings-sidebar .search-field{width:100%;height:36px;}.application-settings-sidebar nav{overflow-y:auto;min-height:0;}.application-settings-sidebar nav section+section{margin-top:22px;}.application-settings-sidebar nav h3{font-size:10px;color:var(--subtle);font-weight:500;margin:0 10px 9px;}.settings-section-button{width:100%;display:flex;align-items:center;gap:10px;height:40px;min-width:0;border:1px solid transparent;border-radius:5px;background:transparent;color:var(--muted);padding:0 11px;text-align:left;font-size:12px;transition:background 140ms,color 140ms;}.settings-section-button+.settings-section-button{margin-top:4px;}.settings-section-button.active{background:var(--surface);border-color:var(--line);color:var(--accent);box-shadow:var(--shadow);}.application-settings-main{display:flex;flex-direction:column;min-width:0;min-height:0;}.application-settings-header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:22px 30px 20px;border-bottom:1px solid var(--line);}.application-settings-header h2{display:flex;align-items:center;gap:10px;font-size:18px;line-height:1.5;}.application-settings-header h2 svg{color:var(--muted);}.settings-close{flex:none;}.application-settings-content{flex:1;min-height:0;overflow:auto;overscroll-behavior:contain;padding:22px 30px 28px;}.settings-directory-feedback{display:flex;align-items:center;gap:7px;color:var(--green);font-size:12px;padding:12px 30px 0;}.settings-directory-feedback.error{color:var(--red);}.settings-no-match{padding:10px;color:var(--muted);font-size:11px;}.settings-search-empty{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:16px;height:100%;color:var(--muted);}.settings-search-empty h3{font-size:14px;font-weight:500;}.application-settings-dialog button:focus-visible,.application-settings-sidebar input:focus-visible{outline:2px solid var(--accent);outline-offset:2px;}.settings-section-button:active{transform:translateY(1px);}@media(hover:hover){.settings-section-button:not(.active):hover{color:var(--ink);background:var(--surface-muted);}}@media(max-width:900px){.settings-backdrop{padding:16px;}.application-settings-dialog{width:calc(100vw - 32px);height:calc(100dvh - 32px);max-height:calc(100dvh - 32px);grid-template-columns:176px minmax(0,1fr);}.application-settings-sidebar{padding:22px 11px;}.application-settings-header{padding:20px 22px;}.application-settings-content{padding:18px 22px 24px;}}.settings-dialog-enter-active,.settings-dialog-leave-active{transition:opacity 160ms;}.settings-dialog-enter-active .application-settings-dialog,.settings-dialog-leave-active .application-settings-dialog{transition:transform 180ms var(--ease),opacity 160ms;}.settings-dialog-enter-from,.settings-dialog-leave-to{opacity:0;}.settings-dialog-enter-from .application-settings-dialog,.settings-dialog-leave-to .application-settings-dialog{transform:translateY(8px) scale(.99);opacity:0;}@media(prefers-reduced-motion:reduce){.settings-dialog-enter-active,.settings-dialog-leave-active,.settings-dialog-enter-active .application-settings-dialog,.settings-dialog-leave-active .application-settings-dialog,.settings-section-button{transition:none;}}
</style>
